#include "MemoryPanel.h"
#include <imgui.h>
#include <algorithm>
#include <fstream>
#include <numeric>
#include <random>

namespace minios::gui {
MemoryPanel::MemoryPanel(){reset();}
void MemoryPanel::loadExample(int i){if(i==0){blocks_={100,500,200,300,600};processes_={212,417,112,426};}else if(i==1){blocks_={120,80,240,160};processes_={70,130,90,110};}else{blocks_={64,128,256,512};processes_={60,120,220,400};}run();}
void MemoryPanel::reset(){algorithm_=FitAlgorithm::First;freeBlock_=-1;loadExample(0);status_="Loaded memory example";}
void MemoryPanel::run(){try{result_=MemoryManager::allocate(blocks_,processes_,algorithm_);error_.clear();playback_.reset();status_=std::string("Ran ")+MemoryManager::name(algorithm_);}catch(const std::exception&e){error_=e.what();status_="Input error";}}
void MemoryPanel::exportCsv(){std::ofstream f("memory_results.csv");f<<"Process,Size,Block,Fragment\n";for(size_t i=0;i<processes_.size();++i){int b=i<result_.allocation.size()?result_.allocation[i]:-1;f<<'P'<<i<<','<<processes_[i]<<','<<b<<','<<(b>=0?blocks_[b]-processes_[i]:0)<<'\n';}status_=f?"Saved memory_results.csv":"Export failed";}
static void editList(const char*id,std::vector<int>&v){ImGui::PushID(id);int rem=-1;for(int i=0;i<(int)v.size();++i){ImGui::PushID(i);ImGui::SetNextItemWidth(95);ImGui::InputInt("##size",&v[i],0,0);ImGui::SameLine();if(ImGui::SmallButton("X"))rem=i;ImGui::PopID();}if(rem>=0)v.erase(v.begin()+rem);if(ImGui::Button("Add"))v.push_back(64);ImGui::PopID();}
void MemoryPanel::render(){const char* names[]={"First Fit","Best Fit","Worst Fit","Next Fit"};int a=(int)algorithm_;ImGui::BeginChild("mem_left",{330,0},true);ImGui::TextUnformatted("Fixed partitions");ImGui::SetNextItemWidth(180);if(ImGui::Combo("Strategy",&a,names,4)){algorithm_=(FitAlgorithm)a;run();}static int ex=0;const char* examples[]={"Classic","Fragmented","Powers of two"};ImGui::SetNextItemWidth(170);if(ImGui::Combo("Example",&ex,examples,3))loadExample(ex);ImGui::TextUnformatted("Block sizes");editList("blocks",blocks_);ImGui::Separator();ImGui::TextUnformatted("Process sizes");editList("procs",processes_);if(ImGui::Button("Randomize")){std::mt19937 g(std::random_device{}());blocks_.clear();processes_.clear();for(int i=0;i<5;++i)blocks_.push_back(80+g()%421);for(int i=0;i<5;++i)processes_.push_back(40+g()%301);}ImGui::SameLine();if(ImGui::Button("Run"))run();ImGui::SameLine();if(ImGui::Button("Save Results"))exportCsv();if(!error_.empty())ImGui::TextColored({1,.3f,.3f,1},"%s",error_.c_str());
    ImGui::Separator();ImGui::TextUnformatted("Dynamic operations");ImGui::TextWrapped("Select an allocated block to deallocate; Compact removes free partitions and combines their capacity.");ImGui::SetNextItemWidth(100);ImGui::InputInt("Block",&freeBlock_);if(ImGui::Button("Deallocate")&&freeBlock_>=0&&freeBlock_<(int)blocks_.size()){for(size_t i=0;i<result_.allocation.size();++i)if(result_.allocation[i]==freeBlock_)result_.allocation[i]=-1;status_="Deallocated selected block (visual state)";}ImGui::SameLine();if(ImGui::Button("Compact")){std::vector<int>used,free;for(size_t b=0;b<blocks_.size();++b){bool allocated=std::find(result_.allocation.begin(),result_.allocation.end(),(int)b)!=result_.allocation.end();(allocated?used:free).push_back(blocks_[b]);}int sum=std::accumulate(free.begin(),free.end(),0);blocks_=used;if(sum)blocks_.push_back(sum);run();status_="Compacted free capacity";}
    ImGui::Separator();std::vector<std::string>l;std::vector<float>v;for(int i=0;i<4;++i)try{auto c=MemoryManager::allocate(blocks_,processes_,(FitAlgorithm)i);l.push_back(names[i]);v.push_back((float)c.utilization);}catch(...){ }barChart(l,v,"Utilization",150);ImGui::EndChild();ImGui::SameLine();
    ImGui::BeginChild("mem_main",{0,0},true);ImGui::Text("%s",MemoryManager::name(algorithm_));playbackControls("memory",playback_,result_.steps.size());int maxStep=result_.steps.empty()?-1:(int)std::min(playback_.step,result_.steps.size()-1);std::vector<int>shown(processes_.size(),-1);for(int s=0;s<=maxStep;++s)if(result_.steps[s].blockIndex>=0)shown[result_.steps[s].processIndex]=result_.steps[s].blockIndex;
    int total=std::accumulate(blocks_.begin(),blocks_.end(),0);ImVec2 p=ImGui::GetCursorScreenPos();float width=ImGui::GetContentRegionAvail().x;auto*dl=ImGui::GetWindowDrawList();float x=p.x;for(int b=0;b<(int)blocks_.size();++b){float w=total?width*blocks_[b]/total:0;int owner=-1;for(int i=0;i<(int)shown.size();++i)if(shown[i]==b)owner=i;dl->AddRectFilled({x,p.y},{x+w,p.y+85},owner<0?IM_COL32(90,95,105,255):colorFor(owner),2);dl->AddRect({x,p.y},{x+w,p.y+85},IM_COL32_WHITE);std::string label="B"+std::to_string(b)+"\n"+std::to_string(blocks_[b]);dl->AddText({x+5,p.y+8},IM_COL32_WHITE,label.c_str());if(owner>=0){float used=w*processes_[owner]/blocks_[b];dl->AddRectFilled({x+used,p.y},{x+w,p.y+85},IM_COL32(230,180,50,70));for(float hx=x+used-80;hx<x+w;hx+=9)dl->AddLine({std::max(x+used,hx),p.y+85},{std::min(x+w,hx+85),p.y},IM_COL32(250,215,90,160));dl->AddText({x+5,p.y+48},IM_COL32_WHITE,("P"+std::to_string(owner)).c_str());}if(ImGui::IsMouseHoveringRect({x,p.y},{x+w,p.y+85})){ImGui::BeginTooltip();ImGui::Text("Block %d | visual start %.0f | size %d",b,x-p.x,blocks_[b]);ImGui::Text("Owner: %s",owner<0?"Free":("P"+std::to_string(owner)).c_str());if(owner>=0)ImGui::Text("Used %d | internal frag. %d",processes_[owner],blocks_[b]-processes_[owner]);ImGui::EndTooltip();}x+=w;}ImGui::Dummy({width,95});if(maxStep>=0)ImGui::TextWrapped("%s",result_.steps[maxStep].note.c_str());
    if(ImGui::BeginTable("alloc",4,ImGuiTableFlags_Borders|ImGuiTableFlags_RowBg)){for(const char*h:{"Process","Size","Block","Internal frag."})ImGui::TableSetupColumn(h);ImGui::TableHeadersRow();for(int i=0;i<(int)processes_.size();++i){ImGui::TableNextRow();int b=i<(int)result_.allocation.size()?result_.allocation[i]:-1;ImGui::TableNextColumn();ImGui::Text("P%d",i);ImGui::TableNextColumn();ImGui::Text("%d",processes_[i]);ImGui::TableNextColumn();ImGui::Text("%s",b<0?"Unallocated":std::to_string(b).c_str());ImGui::TableNextColumn();ImGui::Text("%d",b<0?0:blocks_[b]-processes_[i]);}ImGui::EndTable();}ImGui::Text("Internal fragmentation: %d | External free capacity: %d | Utilization: %.2f%%",result_.internalFragmentation,result_.externalFragmentation,result_.utilization);ImGui::EndChild();}
} // namespace minios::gui
